def dif_Square(n):
    # We want to check if n = a^2 - b^2 for some integers a,b.
    # Note that a^2 - b^2 = (a-b)(a+b).
    # So n can be expressed as difference of squares if n can be factored as x*y where x and y have the same parity.
    # Because a = (x+y)/2 and b = (y-x)/2 must be integers.
    # So check all factor pairs of n and see if they have the same parity.

    if n == 0:
        return True  # 0 = 0^2 - 0^2

    abs_n = abs(n)
    for x in range(1, int(abs_n**0.5) + 1):
        if abs_n % x == 0:
            y = abs_n // x
            # Check parity of x and y
            if (x + y) % 2 == 0:
                return True
    return False

