def find_Max(arr):
    """
    Finds the largest item in an ordered, shifted (rotated) sequence.
    Assumes arr is a list of comparable items, sorted in ascending order and then rotated.

    Example:
    For arr = [4,5,6,7,0,1,2], the largest item is 7.

    Uses a binary search approach for O(log n) time complexity.
    """
    if not arr:
        return None  # or raise an exception if empty input is invalid

    left, right = 0, len(arr) - 1

    # If the array is not rotated (last element > first element), the max is the last element
    if arr[right] > arr[0]:
        return arr[right]

    while left <= right:
        mid = (left + right) // 2

        # Check if mid is the pivot point where next element is smaller
        if mid < right and arr[mid] > arr[mid + 1]:
            return arr[mid]
        # Check if mid-1 is the pivot point
        if mid > left and arr[mid] < arr[mid - 1]:
            return arr[mid - 1]

        # Decide which side to go
        if arr[mid] >= arr[left]:
            # Left part is sorted, so max must be in right part
            left = mid + 1
        else:
            # Max is in left part
            right = mid - 1

    return arr[0]  # fallback if loop ends (should not happen for valid rotated array)

