    nums.sort()
    n = len(nums)
    for i in range(n):
        # Skip duplicates for i
        if i > 0 and nums[i] == nums[i-1]:
            continue
        target = -nums[i]
        left, right = i + 1, n - 1
        while left < right:
            s = nums[left] + nums[right]
            if s == target:
                return True
            elif s < target:
                left += 1
            else:
                right -= 1
    return False

