def anti_shuffle(s):
    import re

    # Split the string into words and spaces (to keep spaces as is)
    parts = re.findall(r'\S+|\s+', s)
    result = []

    for part in parts:
        if part.isspace():
            # Keep spaces as they are
            result.append(part)
        else:
            # Separate trailing punctuation from the word characters
            # Assuming trailing punctuation means non-alphanumeric chars at the end
            match = re.match(r'([A-Za-z]+)([^A-Za-z]*)', part)
            if match:
                word, punct = match.groups()
                # Sort the word characters ascending (ascii)
                sorted_word = ''.join(sorted(word))
                # Append punctuation as is
                result.append(sorted_word + punct)
            else:
                # If no letters, just append as is
                result.append(part)

    return ''.join(result)

